}

log authzlog { destination = /var/log/tac_plus/authz/%Y/%m/%d.log }
log authclog { destination = /var/log/tac_plus/authc/%Y/%m/%d.log }
log acctlog  { destination = /var/log/tac_plus/acct/%Y/%m/%d.log }
accounting log = acctlog
authentication log = authclog
authorization log = authzlog

mavis module groups {
    resolve gids = yes
    resolve gids attribute = TACMEMBER
    groups filter = /^(guest|staff|ubuntu)$/
}

mavis module external {
    exec = /usr/local/sbin/pammavis "pammavis" "-s" "sshd"
}

user backend = mavis
login backend = mavis chpass
pap backend = mavis

net all {
    net north {
        address = 100.67.0.0/16
    }
    net south {
        address = 100.68.0.0/16 }
}

device world {
    welcome banner = "\nHitherto shalt thou come, but no further. (Job 38.11)\n\n"
    key = QaWsEdRfTgY
    enable 15 = clear test
    address = ::/0
    device south {
        address = 100.99.0.0/16
    }
    device west {
        address = 100.100.0.0/16
    }
}

device localhost {
    address = 127.0.0.1
    welcome banner = "Welcome home\n"
    parent = world # for key and other definitions not set here
}

device rfc {
    address = 172.16.0.0/12
    welcome banner = "Welcome private\n"
    key = labKey
}

profile readwrite {
    script {
        if (service == shell) {
            if (cmd == "")
                set priv-lvl = 15
            permit
        }
    }
}

profile getconfig {
    script {
        if (service == shell) {
            if (cmd == "") {
                set autocmd = "sho run"
                set priv-lvl = 15
                permit
            }
        }
    }
}

profile engineering {
    script {
        if (service == shell) {
            if (cmd == "") {
                set priv-lvl = 7
                permit
            }
            if (cmd =~ /^ping/) deny
            permit
        }
    }
}

profile guest {
    script {
        if (service == shell) {
            if (cmd == "") {
                set priv-lvl = 1
                permit
            }
        }
        permit
    }
}

group admin {
    group north # "admin" is a member
    group south # of both
}

group engineering

group guest

user demo {
    password login = clear demo
    member = engineering,admin
}

user readonly {
    password login = clear readonly
    member = guest
}

user demo1 {
    password login = clear demo
    profile = engineering
}

user demo2 {
    password login = clear demo
    profile {
        # Inline script definition. Alternatively, defining an ACL with the scripts
        # content and refering to that using "script = aclName" works too.
        script {
            if (service == shell) {
                if (cmd == "") {
                    set priv-lvl = 1
                    permit
                }
            }
            permit
        }
    }
}

    ruleset {
        rule from-localhost {
            enabled = yes
            script {
                if (nas == localhost) {
                    if (group ==  admin) {
                        profile = admin
                        permit
                    }
                    if (group ==  engineering ) {
                        profile = engineering
                        permit
                    }
               }
          }
        }
        rule from-rfc {
            enabled = yes
            script {
                if (nas == rfc) {
                    if (group == south) {
                        profile = admin
                        permit
                    }
                    if (group ==  engineering ) {
                        profile = engineering
                        permit
                    }
                }
            }
        }
    }
}

