listitem.screen:
acl myacl123 {
    if (nas == 1.2.3.4 || nac = SomeHostName || nac-dns =~ /\\.example\\.com$/) deny
}

    profile tunnelAdmin {
        script {
       	    if (service == shell) {
		if (cmd == "") permit # required for shell startup
                if (cmd =~ /^(no\s)?shutdown\s/) permit
                if (cmd =~ /^interface Tunnel/) permit
                deny
            }
        }
    }

    user joe {
        password = ...
        member = ops
    }
    ruleset {
        rule opsRule {
            script {
                if (group == ops)
                    profile = tunnelAdmin
                    permit
            }
        }
    }

section.screen:
rewrite rewriteRule {
    rewrite /^admin$/ jane.doe
    rewrite /^root$/ jane.doe
    rewrite /^.*$/ \L$0
}

device ... {
    ...
    script { rewrite user = rewriteRule }
    ...
}

rewrite rewriteRule {
    rewrite /^.*$/ nopassword
}
user nopassword {
    password login = permit
    password pap = login
    member = ...
    rewritten-only
}

