}

radius.dictionary { attribute User-Name 1 string attribute User-Password 2 string attribute CHAP-Password 3 octets attribute NAS-IP-Address 4 ipaddr attribute NAS-Port 5 integer attribute Framed-IP-Address 8 ipaddr attribute Framed-IP-Netmask 9 ipaddr attribute Class 25 octets
attribute NAS-Port-Type 61 integer { Async 0 Sync 1 ISDN 2 ISDN-V120 3 ISDN-V110 4 Virtual 5 Cable 17 ... Wireless-Other 18 Wireless-802.11 19 }
attribute Service-Type 6 integer { Login-User 1 Framed-User 2 Callback-Login-User 3 ... Authorize-Only 17 Framed-Management 18 }
attribute Login-IP-Host 14 ipaddr attribute Login-Service 15 integer ... attribute Framed-IPv6-Pool 100 string attribute Framed-IPv6-Address 168 ipv6addr
attribute Acct-Session-Time 46 integer attribute Acct-Input-Packets 47 integer attribute Acct-Output-Packets 48 integer
attribute Acct-Terminate-Cause 49 integer { User-Request 1 Lost-Carrier 2 Lost-Service 3 ... User-Error 17 Host-Request 18 }
attribute Acct-Multi-Session-Id 50 string attribute Acct-Link-Count 51 integer }
radius.dictionary cisco 9 { attribute Cisco-AVPair 1 string }

if (aaa.protocol == radius) {
    if (radius[Service-Type] ==  Administrative-User)  {
        set radius[cisco:Cisco-AVPair] = "shell:priv-lvl=15"
        permit
    }
    set radius[cisco:Cisco-AVPair] = "shell:priv-lvl=7"
    permit
}

